//! Test support for RustNVR.
//!
//! * [`Fixture`]: small real H.264 and H.265 elementary streams (generated by
//!   `scripts/gen-fixtures.sh`) split into access units;
//! * [`rtp`]: RFC 6184 / RFC 7798 packetization;
//! * [`MockRtspServer`]: a minimal RTSP/1.0 server (TCP interleaved only) that
//!   can be told to drop the connection, stall, or require Basic
//!   authentication, to exercise reconnection paths deterministically.
//!
//! This crate is for tests only and makes no attempt at being a general
//! purpose RTSP server.

pub mod annexb;
pub mod audio;
pub mod rtp;
mod server;

pub use annexb::{AccessUnit, Codec, Fixture};
pub use server::{MockRtspServer, MockServerConfig, ServerStats};
